#!/usr/bin/python3

"""
The Hamming distance between two integers is the number of positions 
at which the corresponding bits are different.

Now your job is to find the total Hamming distance between all pairs 
of the given numbers.

Example:
Input: 4, 14, 2

Output: 6

Explanation: In binary representation, the 4 is 0100, 14 is 1110, and 
2 is 0010 (just showing the four bits relevant in this case). So the 
answer will be: HammingDistance(4, 14) + HammingDistance(4, 2) + 
HammingDistance(14, 2) = 2 + 2 + 2 = 6.
"""

class Solution:

	def hammingDistance(self, x, y):
		distance = 0
		z = x ^ y
		while z != 0:
			z0 = z % 2
			distance += z0
			z = z // 2
		return distance

	def totalHammingDistance(self, nums):
		sum = 0

		# Iterate over all combinations of the array
		size = len(nums)
		for i in range(size-1):
			for j in range(i+1, size):
				sum += self.hammingDistance(nums[i], nums[j])
		return sum


s = Solution()

# test 1
a = [4, 14, 2]
b = s.totalHammingDistance(a)
print("For {}, total Hamming distance: {}".format(a, b))
assert b == 6

# test 1
a = [3, 14, 8, 7]
b = s.totalHammingDistance(a)
print("For {}, total Hamming distance: {}".format(a, b))
assert b == 15

